#!/usr/bin/env python3
"""Generate a binary Homebrew formula from the actual release tarball hashes."""

import argparse
import hashlib
from pathlib import Path
import re


def generate(repo: str, version: str, dist: Path) -> str:
    if not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo):
        raise ValueError("repo must be owner/repository")
    if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+(?:-[A-Za-z0-9.-]+)?", version):
        raise ValueError("version must be a version such as 0.1.0")
    base = f"https://github.com/{repo}"
    lines = [
        "# Generated by scripts/homebrew.py from release archives.",
        "class Mt < Formula",
        '  desc "Coding agents tiled in one terminal with tmux"',
        f'  homepage "{base}"',
        f'  version "{version}"',
        "",
    ]
    for system, platform in [("macos", "darwin"), ("linux", "linux")]:
        lines.append(f"  on_{system} do")
        for chip, arch in [("arm", "arm64"), ("intel", "amd64")]:
            filename = f"mt_{version}_{platform}_{arch}.tar.gz"
            sha = hashlib.sha256((dist / filename).read_bytes()).hexdigest()
            lines.extend([
                f"    on_{chip} do",
                f'      url "{base}/releases/download/v{version}/{filename}"',
                f'      sha256 "{sha}"',
                "    end",
            ])
        lines.extend(["  end", ""])
    lines.extend([
        '  depends_on "tmux"',
        "",
        "  def install",
        '    bin.install "mt"',
        '    pkgshare.install "config.example.yaml"',
        "  end",
        "",
        "  test do",
        '    assert_match version.to_s, shell_output("#{bin}/mt --version")',
        "  end",
        "end",
        "",
    ])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", required=True, help="GitHub owner/repository")
    parser.add_argument("--version", required=True)
    parser.add_argument("--dist", type=Path, default=Path("dist"))
    parser.add_argument("--output", type=Path, default=Path("dist/mt.rb"))
    args = parser.parse_args()
    try:
        formula = generate(args.repo, args.version, args.dist)
    except (ValueError, OSError) as exc:
        parser.error(str(exc))
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(formula, encoding="utf-8")
    print(f"Wrote {args.output}")


if __name__ == "__main__":
    main()
